\title{Higher-Dimensional Pythagorean Trees:\\
Descent Complexes, Exact Branching, and Hyperbolic Growth}
\author{Aristotle}
\date{21 August 2026}

\begin{document}
\maketitle

\begin{abstract}
The Berggren tree organizes all primitive Pythagorean triples into an infinite ternary tree
generated by three integral reflections of the Lorentz form $x_1^2+x_2^2-y^2$. We develop the
general-$n$ theory of the analogous structure on the null cone of $x_1^2+\cdots+x_n^2-y^2$,
whose integer points are the primitive Pythagorean $n$-tuples. To each null point we attach its
\emph{descent complex}: the family of sign patterns $\varepsilon\in\{\pm1\}^n$, recorded by
their minus-sets $S$, whose associated integral reflection strictly lowers the height. We prove
that this family is downward closed, hence an abstract simplicial complex, and that the
Pythagorean relation forces the dimension bound $\#S\le n-2$, with the strengthening that
disjoint faces $S,T$ satisfy $\#(S\cup T)^{c}\ge2$. Consequences: in dimension three at most one
single sign flip descends, so every positive Pythagorean quadruple has exactly six or exactly
seven children, the dichotomy being decided by an Egyptian-fraction inequality; both values occur
infinitely often, so the higher graph is \emph{not} a regular tree. Dually, every node in
dimension $n$ has at least $n+1$ children, attained exactly for $n=2$. In dimension four the
face bound is sharp, via a Pell family $(1,1,t,t;d)$ with $d^2-2t^2=2$. Metrically, one
reflection multiplies the height by at most $\rho_n=(\sqrt n+1)/(\sqrt n-1)$; we show
$\rho_2=(1+\sqrt2)^2$ and $\rho_3=2+\sqrt3$ are norm-one units, that $2+\sqrt3$ is the
fundamental unit of $\Z[\sqrt3]$, that $\rho_n\downarrow1$, and that the critical exponent
$\log(\text{branching})/\log\rho$ crosses $1$ between dimensions two and three. Over $\Z$ the
constant $\rho_3$ is an unattained supremum. Finally, height-neutral moves are exactly the fixed
points of the generators, and the number of such \emph{mirror nodes} with first coordinate $a$
is exactly $\tau(a^2)$.
\end{abstract}

\section{Introduction}

\subsection{The classical picture}
A \emph{primitive Pythagorean triple} is a triple $(a,b,c)$ of positive integers with
$a^2+b^2=c^2$ and $\gcd(a,b,c)=1$. Berggren (1934) observed that the three integer matrices
\[
U=\begin{pmatrix}1&-2&2\\2&-1&2\\2&-2&3\end{pmatrix},\quad
A=\begin{pmatrix}1&2&2\\2&1&2\\2&2&3\end{pmatrix},\quad
D=\begin{pmatrix}-1&2&2\\-2&1&2\\-2&2&3\end{pmatrix}
\]
preserve $a^2+b^2=c^2$ and generate from $(3,4,5)$ an infinite ternary tree containing every
primitive triple exactly once.

The matrices are not arbitrary. Write the Lorentz form of signature $(n,1)$,
\[
Q_n(x_1,\dots,x_n,y)=x_1^2+\cdots+x_n^2-y^2,
\]
with null cone $\mathcal C_n=\{Q_n=0\}$. A primitive Pythagorean $n$-tuple is precisely a
primitive positive integer point of $\mathcal C_n$; the Berggren matrices lie in
$\mathrm O(Q_2;\Z)$ and are conjugates of a single reflection by diagonal sign matrices.

\subsection{The question and the answer}
Does the Berggren tree generalize to a regular tree of Pythagorean $n$-tuples? The finite
generating set exists ($2^n$ signed reflections, all involutions), the hyperbolic embedding
exists, and the growth constant is an explicit quadratic unit --- but regularity fails, in a
completely computable way. The structure that explains everything is the descent complex.

\section{The null cone and its signed reflections}

\begin{definition}[Pythagorean $n$-tuple]
A pair $(x;d)$ with $x\in\Z^n$, $d\in\Z$ is a \emph{Pythagorean $n$-tuple} if
$\sum_{i=1}^n x_i^2=d^2$. It is \emph{primitive} if $\gcd(x_1,\dots,x_n,d)=1$ and
\emph{positive} if all $x_i>0$ and $d>0$.
\end{definition}

\begin{definition}[Sign pattern, signed sum]
A \emph{sign pattern} is $\varepsilon\in\{\pm1\}^n$, encoded by its minus-set
$S=\{i:\varepsilon_i=-1\}$. The \emph{signed sum} is
$\sigma_S(x)=\varepsilon\cdot x=\sum_{i\notin S}x_i-\sum_{i\in S}x_i$.
\end{definition}

\begin{lemma}[Signed sum decomposition]\label{lem:decomp}
$\sigma_S(x)=\sum_{i=1}^n x_i-2\sum_{i\in S}x_i$; in particular $\sigma_\emptyset(x)=\sum_i x_i$.
\end{lemma}
\begin{proof}
Termwise $-x_i=x_i-2x_i$ for $i\in S$ and $x_i=x_i-0$ otherwise; sum and split.
\end{proof}

\begin{definition}[Signed reflection]
For a sign pattern $\varepsilon$ set $k=\varepsilon\cdot x-d$ and
\[
R_\varepsilon(x;d)=\bigl(x_1-\varepsilon_1k,\dots,x_n-\varepsilon_nk;\ d-k\bigr).
\]
For $n=3$ one may take the reflection matrix
$R=\left(\begin{smallmatrix}0&-1&-1&1\\-1&0&-1&1\\-1&-1&0&1\\-1&-1&-1&2\end{smallmatrix}\right)$
and conjugate by $S_\varepsilon=\mathrm{diag}(\varepsilon_1,\varepsilon_2,\varepsilon_3,1)$,
obtaining the eight generators $R_\varepsilon=S_\varepsilon R S_\varepsilon$.
\end{definition}

\begin{proposition}[Basic properties]\label{prop:basic}
For every sign pattern $\varepsilon$:
(i) $R_\varepsilon$ is an integral automorphism of $Q_n$, hence maps Pythagorean tuples to
Pythagorean tuples; (ii) $R_\varepsilon^2=I$, so the generated group is a quotient of a free
product of copies of $\Z/2$; (iii) $R_\varepsilon$ preserves the content
$\gcd(x_1,\dots,x_n,d)$, hence primitivity; (iv) the height transforms by
$d\mapsto 2d-\varepsilon\cdot x=2d-\sigma_S(x)$.
\end{proposition}
\begin{proof}[Proof sketch]
The sign matrices are orthogonal on the space part and fix the time coordinate; $R$ preserves
$Q_n$ by direct computation; products of form-preserving integral matrices are form-preserving.
Since $S_\varepsilon^2=R^2=I$ we get $R_\varepsilon^2=I$, whence also (iii), each coordinate map
being invertible over $\Z$. Item (iv) is immediate from the definition of $k$.
\end{proof}

\begin{definition}[Descent, neutrality, child]
For a positive Pythagorean tuple $(x;d)$ and a sign set $S$: $S$ \emph{descends} if
$\sigma_S(x)>d$; $S$ is \emph{neutral} if $\sigma_S(x)=d$ (equivalently $R_\varepsilon$ fixes the
node); $S$ is a \emph{child move} if $\sigma_S(x)<d$. The \emph{branching number} is the number
of child moves and the \emph{descent complex} $\mathcal D(x,d)$ is the family of descending sets.
\end{definition}

Since $(\sum_i x_i)^2\ge\sum_i x_i^2=d^2$ for non-negative coordinates, the all-plus pattern is
never a child.

\section{The descent complex}

\begin{theorem}[Downward Closure]\label{thm:mono}
Let $x$ have non-negative coordinates. If $T$ descends and $S\subseteq T$ then $S$ descends.
Hence $\mathcal D(x,d)$ is an abstract simplicial complex on $\{1,\dots,n\}$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:decomp} descent for $T$ reads $\sum_i x_i-2\sum_{i\in T}x_i>d$. Since
$S\subseteq T$ and coordinates are non-negative, $\sum_{i\in S}x_i\le\sum_{i\in T}x_i$, so
$\sum_i x_i-2\sum_{i\in S}x_i\ge\sum_i x_i-2\sum_{i\in T}x_i>d$.
\end{proof}

\begin{lemma}[Coordinate bound]\label{lem:coord}
For a Pythagorean tuple with $d\ge0$ and any $j$, $x_j\le d$.
\end{lemma}
\begin{proof}
$x_j^2\le\sum_i x_i^2=d^2$; take square roots using $d\ge0$.
\end{proof}

\begin{lemma}[Two-index lemma]\label{lem:two}
Let $(x;d)$ be Pythagorean with $d\ge0$ and $T$ satisfy $\sum_{i\in T}x_i>d$. Then $\#T\ge2$.
\end{lemma}
\begin{proof}
$T=\emptyset$ gives $0>d$, impossible; $T=\{j\}$ gives $x_j>d$, contradicting
Lemma~\ref{lem:coord}.
\end{proof}

\begin{theorem}[Dimension Bound]\label{thm:dim}
Let $(x;d)$ be Pythagorean with $x_i\ge0$, $d\ge0$. Every face $S\in\mathcal D(x,d)$ satisfies
$\#S^{c}\ge2$, i.e.\ $\#S\le n-2$.
\end{theorem}
\begin{proof}
Descent says $\sum_{i\in S^{c}}x_i-\sum_{i\in S}x_i>d$; since $\sum_{i\in S}x_i\ge0$ we get
$\sum_{i\in S^{c}}x_i>d$, and Lemma~\ref{lem:two} applies with $T=S^{c}$.
\end{proof}

\begin{theorem}[Disjoint Faces]\label{thm:disj}
If $S,T$ are disjoint faces of $\mathcal D(x,d)$ (with $d\ge0$), then $\#(S\cup T)^{c}\ge2$.
\end{theorem}
\begin{proof}
Adding the two descent inequalities and using $\sum_{i\in S\cup T}x_i=\sum_{i\in S}x_i+
\sum_{i\in T}x_i$ gives $2\sum_i x_i-2\sum_{i\in S\cup T}x_i>2d$, i.e.
$\sum_{i\in(S\cup T)^{c}}x_i>d$; apply Lemma~\ref{lem:two}.
\end{proof}

\begin{remark}
In dimension two Theorem~\ref{thm:dim} allows only $S=\emptyset$: this is the source of Berggren
regularity. In dimension three it allows $\emptyset$ and singletons; in dimension four, edges.
\end{remark}

\section{Dimension three: exact branching}

\begin{theorem}[Unique Descent]\label{thm:unique}
For a Pythagorean quadruple with $d\ge0$, if $\{i\}$ and $\{j\}$ both descend then $i=j$.
\end{theorem}
\begin{proof}
If $i\ne j$ the singletons are disjoint faces, so $\#\{i,j\}^{c}\ge2$ by Theorem~\ref{thm:disj};
but $n=3$ gives $\#\{i,j\}^{c}=1$.
\end{proof}

\begin{definition}[Weak defect]
A positive quadruple $(a,b,c,d)$ has a \emph{weak defect} if $d\le-a+b+c$ or $d\le a-b+c$ or
$d\le a+b-c$.
\end{definition}

\begin{theorem}[Egyptian-fraction form]\label{thm:harmonic}
For a positive Pythagorean quadruple,
\[
\text{weak defect}\iff a(b+c)\le bc\ \text{ or }\ b(a+c)\le ac\ \text{ or }\ c(a+b)\le ab,
\]
i.e.\ iff $\tfrac1b+\tfrac1c\le\tfrac1a$ or one of its permutations.
\end{theorem}
\begin{proof}[Proof sketch]
For the first clause, $d\le b+c-a$ with $a^2+b^2+c^2=d^2$ gives
$d^2\le(b+c-a)^2=d^2+2\bigl(bc-a(b+c)\bigr)$, hence $a(b+c)\le bc$. Conversely $a(b+c)\le bc$
forces $b+c-a>0$ and the same identity yields $(b+c-a)^2\ge d^2$; take positive square roots.
The other clauses are the same computation up to permutation.
\end{proof}

\begin{theorem}[Exact Branching, $n=3$]\label{thm:branch}
A positive Pythagorean quadruple has exactly $6$ children if it has a weak defect and exactly $7$
otherwise.
\end{theorem}
\begin{proof}
The all-plus pattern is a non-child, since $(a+b+c)^2\ge d^2$. Any pattern with $\#S\ge2$ is a
child: then $\#S^{c}\le1$, so $\sum_{i\in S^{c}}x_i\le d$ by Lemma~\ref{lem:two}, and
$\sigma_S(x)\le d-\sum_{i\in S}x_i<d$ by positivity. So the only possible further non-children
are the three single flips, and a single flip is a non-child exactly when the corresponding weak
defect clause holds. By the argument of Theorem~\ref{thm:disj} (with $\le$ in place of $<$) at
most one single flip can be a non-child. Hence the non-children number $1$ or $2$, giving $7$ or
$6$ children.
\end{proof}

\begin{theorem}[Six-child family]
For $m\ge2$, $(1,2m,2m^2,2m^2+1)$ is a Pythagorean quadruple with exactly six children.
\end{theorem}
\begin{proof}
$1+4m^2+4m^4=(2m^2+1)^2$, and $2m^2+1\le-1+2m+2m^2$ iff $m\ge1$; apply Theorem~\ref{thm:branch}.
\end{proof}

\begin{theorem}[Seven-child family]
For $m\ge2$, $(2m,2m,2m^2-1,2m^2+1)$ is a \emph{primitive} Pythagorean quadruple with exactly
seven children.
\end{theorem}
\begin{proof}
$4m^2+4m^2+(2m^2-1)^2=(2m^2+1)^2$. A common divisor of the last two coordinates divides their
difference $2$, but $2m^2-1$ is odd, so the content is $1$. Each defect clause fails for $m\ge2$;
apply Theorem~\ref{thm:branch}.
\end{proof}

\begin{corollary}
The Pythagorean quadruple graph is not vertex-regular: both branching numbers occur infinitely
often.
\end{corollary}

\section{A universal branching bound}

\begin{theorem}[Universal Branching Bound]\label{thm:univ}
Let $n\ge2$ and $(x;d)$ be Pythagorean with $x_i>0$, $d\ge0$. Every sign set $S$ with
$\#S^{c}\le1$ is a child move; hence the node has at least $n+1$ children.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:two}, $\#S^{c}\le1$ implies $\sum_{i\in S^{c}}x_i\le d$, so
$\sigma_S(x)\le d-\sum_{i\in S}x_i<d$ because $S\neq\emptyset$ and coordinates are positive.
There are $n+1$ such sets: the full set and the $n$ complements of singletons.
\end{proof}

\begin{corollary}[Berggren minimality]
For $n=2$ the bound gives $3$ and the true branching number is $3$; the Berggren tree is the
minimally branching member of the family, precisely because the dimension bound leaves room only
for the empty face.
\end{corollary}

\section{Dimension four: sharpness via Pell's equation}

\begin{definition}
Let $\pi(t,d)=(3t+2d,\,4t+3d)$, $(t_0,d_0)=(1,2)$, $(t_{k+1},d_{k+1})=\pi(t_k,d_k)$, and attach
the quintuple $Q_t=(1,1,t,t;d)$.
\end{definition}

\begin{lemma}[Pell invariance]\label{lem:pell}
$d_k^2-2t_k^2=2$ for all $k$; moreover $d_k\ge k+2$, $t_k\ge1$, and $t_k\ge7$ for $k\ge1$.
\end{lemma}
\begin{proof}
$(4t+3d)^2-2(3t+2d)^2=d^2-2t^2$, and $4-2=2$ at the base point. From $t\ge1$, $d\ge2$ one gets
$3t+2d\ge7$ and $4t+3d\ge d+1$; induct.
\end{proof}

The first solutions are $(1,2),(7,10),(41,58),(239,338),(1393,1970)$.

\begin{theorem}[Two-element face]\label{thm:twoface}
If $t\ge4$, $d>0$ and $d^2=2t^2+2$, then $Q_t$ is a primitive Pythagorean $4$-tuple and
$S=\{1,2\}$ is a face of its descent complex.
\end{theorem}
\begin{proof}
$1+1+t^2+t^2=d^2$, and the coordinate $1$ forces primitivity. Descent for $S=\{1,2\}$ means
$2t-2>d$; both sides positive, and $(2t-2)^2>2t^2+2\iff 2\bigl((t-2)^2-3\bigr)>0$, true for
$t\ge4$.
\end{proof}

\begin{theorem}[Sharpness in dimension four]
For every $N$ there is a primitive Pythagorean quintuple of height $>N$ whose descent complex
contains a face of size $2=n-2$. Hence the bound of Theorem~\ref{thm:dim} is attained for $n=4$.
\end{theorem}
\begin{proof}
Choose $k$ with $d_k>N$; then $t_k\ge7\ge4$ by Lemma~\ref{lem:pell}, and
Theorem~\ref{thm:twoface} applies.
\end{proof}

\begin{remark}
Two-element faces are impossible for $n=3$ (Theorem~\ref{thm:unique}); the descent complex is a
genuinely dimension-dependent invariant. Putting $n-2$ coordinates equal to $1$ and two equal to
$t$ turns the general face condition into ``$d^2-2t^2=n-2$ and $2t-(n-2)>d$'', a representability
question for $x^2-2y^2$.
\end{remark}

\section{Metric growth}

Projectivizing $\mathcal C_n\subset\R^{n,1}$ gives the boundary sphere of $\HH^n$, on which
$\mathrm O(Q_n;\Z)$ acts by isometries; the height behaves as an exponentiated Busemann function,
so a move displaces a node hyperbolically by $\log(d'/d)$.

\begin{definition}
$\rho_n=\dfrac{\sqrt n+1}{\sqrt n-1}$ for $n\ge2$. One move satisfies $d'\le\rho_n d$, sharply on
the real cone, the extremum being the symmetric ray $x_1=\cdots=x_n=d/\sqrt n$.
\end{definition}

\begin{theorem}[Closed forms and units]
$\rho_2=3+2\sqrt2=(1+\sqrt2)^2$ and $\rho_3=2+\sqrt3$. Both are units of norm one:
$(3+2\sqrt2)(3-2\sqrt2)=1$ and $(2+\sqrt3)(2-\sqrt3)=1$.
\end{theorem}

\begin{theorem}[Fundamental unit]
$2+\sqrt3$ is the smallest unit greater than $1$ with positive integer coordinates in
$\Z[\sqrt3]$: if $a,b>0$ and $a^2-3b^2=1$ then $a+b\sqrt3\ge2+\sqrt3$.
\end{theorem}
\begin{proof}
$b\ge1$ forces $a^2=3b^2+1\ge4$, so $a\ge2$ and $a+b\sqrt3\ge2+\sqrt3$.
\end{proof}

Thus $\log\rho_3$ is the exact structural analogue for quadruples of the silver-ratio exponent
$\log(1+\sqrt2)$ for triples.

\begin{theorem}[Monotonicity]
$\rho_n=1+\dfrac{2}{\sqrt n-1}$ is strictly decreasing in $n\ge2$ and $\rho_n\to1$.
\end{theorem}

\begin{definition}[Critical exponent]
For branching $k$ and one-move ratio $\rho$, set $\delta(k,\rho)=\log k/\log\rho$, the number of
nodes per unit hyperbolic displacement.
\end{definition}

\begin{theorem}[Growth exponent jump]
\[
\delta_2=\frac{\log3}{\log(3+2\sqrt2)}\approx0.6233<1<\frac{\log6}{\log(2+\sqrt3)}\approx1.3606
\le\delta_3 .
\]
\end{theorem}
\begin{proof}
$3+2\sqrt2>3>1$ gives $\delta_2<1$; $1<2+\sqrt3<6$ gives $\log6/\log(2+\sqrt3)>1$.
\end{proof}

Higher dimension slows each move ($\rho_3\approx3.732<5.828\approx\rho_2$) but multiplies the
branching ($6$ or $7$ versus $3$); branching wins.

\begin{theorem}[Strict integral growth]
For an integral Pythagorean quadruple with $a,b,c\ge0$, $d>0$ one has $a+b+c<\sqrt3\,d$, and
therefore $d'<(2+\sqrt3)d$ for every reflection move: the sharp real constant is an unattained
supremum on the integral tree.
\end{theorem}
\begin{proof}
Cauchy--Schwarz gives $(a+b+c)^2\le3d^2$ with equality iff $a=b=c$, which would force
$3a^2=d^2$; for $a\ne0$ this makes $\sqrt3$ rational, and $a=0$ forces $d=0$.
\end{proof}

\section{Mirror nodes and the divisor law}

\begin{theorem}[Mirror characterization]
$R_\varepsilon$ fixes $(x;d)$ if and only if $\varepsilon\cdot x=d$, i.e.\ iff the move is
height-neutral. Such nodes are the lattice points on the mirror hyperplanes of the reflection
group.
\end{theorem}
\begin{proof}
The action is $(x_i-\varepsilon_i k;\,d-k)$ with $k=\varepsilon\cdot x-d$; the last coordinate is
fixed iff $k=0$, and $k=0$ makes the whole map the identity.
\end{proof}

In dimension two there are no mirror nodes and the group acts freely; in dimension three they are
infinite in number.

\begin{theorem}[Infinite primitive mirror family]
For every $m\ge1$ the quadruple $\bigl(m,\,m+1,\,m(m+1),\,m^2+m+1\bigr)$ is primitive
Pythagorean, is fixed by the generator flipping the first coordinate, and has exactly six
children. The case $m=1$ is $(1,2,2,3)$.
\end{theorem}
\begin{proof}
$m^2+(m+1)^2+m^2(m+1)^2=(m^2+m+1)^2$; a common divisor of $m$ and $m+1$ divides $1$;
$-m+(m+1)+m(m+1)=m^2+m+1$; and this is the equality case of a weak defect clause, so
Theorem~\ref{thm:branch} gives six children.
\end{proof}

\begin{theorem}[Uniqueness of the stabilizing generator]
Apart from the all-plus generator, at most one generator fixes a given positive Pythagorean
quadruple; stabilizers are trivial or cyclic of order two. In particular mirror nodes always have
six children, and branching $7$ occurs only off the mirrors.
\end{theorem}

\begin{theorem}[Factorization bijection]\label{thm:fact}
(i) For integers $a,p,q$ with $pq=a^2$, the quadruple $(a,\,a+p,\,a+q,\,a+p+q)$ is Pythagorean
and satisfies $-a+(a+p)+(a+q)=a+p+q$.
(ii) Conversely, if $(a,b,c,d)$ is a positive Pythagorean quadruple with $-a+b+c=d$, then
$p=b-a>0$, $q=c-a>0$, $pq=a^2$ and $d=a+p+q$.
\end{theorem}
\begin{proof}
(i) $a^2+(a+p)^2+(a+q)^2-(a+p+q)^2=2a^2-2pq=0$. (ii) Substituting $d=b+c-a$ gives $bc=a(b+c)$,
hence $(b-a)(c-a)=bc-a(b+c)+a^2=a^2$; and $bc=a(b+c)>ab$ gives $c>a$, similarly $b>a$.
\end{proof}

\begin{theorem}[Divisor Law]
For each positive integer $a$, the number of mirror nodes for the first-coordinate reflection
with first coordinate $a$ equals $\tau(a^2)$, the number of divisors of $a^2$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:fact} the map $(a,b,c,d)\mapsto b-a$ is a bijection onto the positive
divisors of $a^2$, with inverse $p\mapsto(a,\,a+p,\,a+a^2/p,\,a+p+a^2/p)$.
\end{proof}

\begin{example}
$\tau(4)=3$: the mirror nodes over $a=2$ are $(2,3,6,7)$, $(2,4,4,6)$, $(2,6,3,7)$, the first
primitive. $\tau(36)=9$ over $a=6$. Since $a^2$ is a square, $\tau(a^2)$ is odd, the unpaired
divisor $p=q=a$ giving the symmetric node $(a,2a,2a,3a)$.
\end{example}

This is the higher-dimensional replacement for the arithmetic counting laws attached to the star
lines of the planar theory: where the plane counts with the totient function, space counts with
the divisor function.

\section{Algorithms}

\textbf{(A) Branching classifier.} Compare $-a+b+c$, $a-b+c$, $a+b-c$ with $d$; return $6$ if any
is $\ge d$, else $7$. Cost $O(1)$; correctness by Theorem~\ref{thm:branch}, with the equivalent
reciprocal test of Theorem~\ref{thm:harmonic}.

\smallskip\noindent
\textbf{(B) Child enumeration.} For each of the $2^n$ patterns compute $\sigma=\varepsilon\cdot
x$, keep $\sigma<d$, and emit $(x_i-\varepsilon_i(\sigma-d);\,2d-\sigma)$. Cost $O(2^nn)$ per
node; heights strictly increase, so breadth-first search by height terminates at any cutoff.

\smallskip\noindent
\textbf{(C) Descent complex.} Test $\sigma_S(x)>d$ over subsets, pruning by
Theorem~\ref{thm:mono}: once a set fails, so do all supersets.

\smallskip\noindent
\textbf{(D) Pell ladder.} Iterate $(t,d)\mapsto(3t+2d,4t+3d)$ from $(1,2)$; heights grow with
ratio $3+2\sqrt2$.

\section{Discussion and future work}

\subsection{What generalizes}
For $n=2$ the descent complex is $\{\emptyset\}$, there are no neutral patterns, and branching is
exactly $3$ --- a regular ternary tree, minimal by Theorem~\ref{thm:univ}. For $n=3$ the complex
is at most a point plus a vertex, branching is $6$ or $7$, and mirror nodes obey a divisor law.
For $n=4$ two-element faces occur infinitely often. The transition $n=2\to3$ is where the tree
becomes a graph with a nontrivial local invariant; $n=3\to4$ is where the complex acquires
positive dimension.

\subsection{Applications}
The moves give a certified generation procedure for primitive Pythagorean $n$-tuples with
quantified exponential rate; the mirror family and divisor law give explicit dense families of
integral points on spheres; the critical exponent is the invariant governing the Poincar\'e
series of the reflection group on $\HH^n$, and it crosses $1$ between dimensions two and three.

\subsection{Future directions}

\begin{conjecture}[Sharpness of the face bound in every dimension]
For every $n\ge3$ there exist infinitely many primitive Pythagorean $n$-tuples whose descent
complex contains a face of size exactly $n-2$.
\end{conjecture}
A face of size $n-2$ is a solution of a generalized Pell system: taking two ``large'' coordinates
equal to $t$ and the $n-2$ small ones equal to $1$ reduces the condition to $d^2-2t^2=n-2$
together with $2t-(n-2)>d$, so sharpness in dimension $n$ is equivalent to representability of
$n-2$ by $x^2-2y^2$ (or by an alternative shape when that fails, e.g.\ $n=5$, where
$x^2-2y^2=3$ is insoluble). The case $n=4$ is a theorem via exactly this mechanism, and the
obstruction for the remaining $n$ is an explicit congruence condition; a case analysis modulo $8$
plus a second family should settle it.

\begin{conjecture}[Exact branching spectrum]
For each $n$ the set of branching numbers realized by nodes with positive coordinates is exactly
$\{2^n-k\}$, where $k$ ranges over the possible sizes of the non-child family; this family is
always a simplicial complex whose face numbers are governed by harmonic inequalities of the shape
$x_i\bigl(\sum_{j\ne i}x_j-x_i\bigr)\le\cdots$. For $n=3$ this gives $\{6,7\}$; for $n=4$ the
conjecture is $\{11,12,13,14,15\}$.
\end{conjecture}
Non-children are precisely the faces of the \emph{weak} descent complex, so the branching number
is $2^n$ minus the number of faces, and the spectrum is a statement about which downward-closed
families are realizable by null vectors.

\medskip\noindent
Further problems: (1) completeness --- does the reflection graph rooted at $(1,2,2,3)$ reach
every primitive quadruple? (2) the density of two-parent nodes; (3) the exact value of $\delta_3$,
requiring the average branching weighted by the density of six- versus seven-child nodes;
(4) the analogue of the divisor law in dimension $n\ge4$.

\section*{Summary of results}
\begin{center}
\begin{tabular}{ll}
\toprule
Result & Statement\\
\midrule
Downward closure & Descending sign sets form a simplicial complex\\
Dimension bound & Every face satisfies $\#S\le n-2$\\
Disjoint faces & Disjoint faces $S,T$ satisfy $\#(S\cup T)^{c}\ge2$\\
Unique descent ($n=3$) & At most one single sign flip descends\\
Exact branching ($n=3$) & Branching is $6$ (weak defect) or $7$\\
Egyptian-fraction law & Defect $\iff a(b+c)\le bc$ or a permutation\\
Universal bound & Branching $\ge n+1$, attained exactly at $n=2$\\
Sharpness ($n=4$) & Pell quintuples $(1,1,t,t;d)$, $t\ge4$, have a $2$-face\\
Growth constant & $\rho_n=(\sqrt n+1)/(\sqrt n-1)$; $\rho_3=2+\sqrt3$ fundamental in $\Z[\sqrt3]$\\
Critical exponent & $\log3/\log(3+2\sqrt2)<1<\log6/\log(2+\sqrt3)$\\
Strict integral growth & $a+b+c<\sqrt3\,d$, so $d'<(2+\sqrt3)d$\\
Divisor law & Exactly $\tau(a^2)$ mirror nodes with first coordinate $a$\\
\bottomrule
\end{tabular}
\end{center}

