INPUT  x = (x_1..x_n) non-negative integers, d >= 0 with sum x_i^2 = d^2
OUTPUT the faces of the descent complex, its f-vector, and the bound check

function SIGNEDSUM(S, x):
    return (sum of all x_i) - 2 * (sum of x_i for i in S)

function DESCENDS(S, x, d):
    return SIGNEDSUM(S, x) > d

function DESCENTCOMPLEX(x, d):
    faces <- empty list
    level <- { the empty set } if DESCENDS(empty set, x, d) else empty
    append level to faces
    while level is non-empty:
        candidates <- empty set
        for each S in level:
            for each index j greater than max(S):        # canonical extension
                candidates <- candidates union { S union {j} }
        level <- { S in candidates : DESCENDS(S, x, d) }  # monotone pruning
        append level to faces
    return faces

ASSERT max{ |S| : S in faces } <= n - 2       # Dimension Bound Theorem

INPUT  a positive Pythagorean quadruple (a, b, c, d)
OUTPUT its branching number, and the list of child nodes

function WEAKDEFECT(a, b, c, d):
    return (d <= -a + b + c) or (d <= a - b + c) or (d <= a + b - c)

function HARMONICDEFECT(a, b, c):                 # equivalent reciprocal form
    return (a*(b+c) <= b*c) or (b*(a+c) <= a*c) or (c*(a+b) <= a*b)

function BRANCHINGNUMBER(a, b, c, d):
    require a,b,c,d > 0 and a^2 + b^2 + c^2 = d^2
    if WEAKDEFECT(a, b, c, d): return 6 else return 7

function CHILDREN(x, d):
    for each sign pattern eps in {+1,-1}^n:
        s <- dot(eps, x)
        if s < d:
            k <- s - d
            emit (eps, (x_i - eps_i * k for all i ; d - k))

function BFSBYHEIGHT(root, H):
    seen <- {root}; frontier <- [root]
    while frontier non-empty:
        next <- []
        for each node in frontier:
            for each (eps, child) in CHILDREN(node):
                if height(child) <= H and child not in seen:
                    add child to seen and to next
        frontier <- next
    return seen

