"""Exact branching classifier and certified child enumeration in dimension three.

The branching number of a positive Pythagorean quadruple (a,b,c,d) is 6 when a single
sign flip fails to raise the height -- equivalently when one of the Egyptian-fraction
inequalities 1/b + 1/c <= 1/a (or a permutation) holds -- and 7 otherwise.  The
classifier runs in O(1) integer operations; the enumerator produces the children in
O(2^n n) and is certified to output Pythagorean tuples of strictly larger height.
"""

from __future__ import annotations

import itertools
from typing import Iterator, List, Sequence, Tuple

Quad = Tuple[int, int, int, int]


def weak_defect(a: int, b: int, c: int, d: int) -> bool:
    """Some single sign flip fails to raise the height."""
    return d <= -a + b + c or d <= a - b + c or d <= a + b - c


def harmonic_defect(a: int, b: int, c: int) -> bool:
    """Equivalent reciprocal form: 1/b + 1/c <= 1/a, or a permutation."""
    return a * (b + c) <= b * c or b * (a + c) <= a * c or c * (a + b) <= a * b


def branching_number(a: int, b: int, c: int, d: int) -> int:
    """Exactly 6 or 7, by the Exact Branching Theorem."""
    assert a > 0 and b > 0 and c > 0 and d > 0
    assert a * a + b * b + c * c == d * d, "not a Pythagorean quadruple"
    return 6 if weak_defect(a, b, c, d) else 7


def children(x: Sequence[int], d: int) -> Iterator[Tuple[Tuple[int, ...], Tuple[Tuple[int, ...], int]]]:
    """Yield (sign pattern, child node) for every height-raising reflection."""
    n = len(x)
    for eps in itertools.product((1, -1), repeat=n):
        s = sum(e * xi for e, xi in zip(eps, x))
        if s < d:
            k = s - d
            yield eps, (tuple(xi - e * k for e, xi in zip(eps, x)), d - k)


def bfs_by_height(root: Tuple[Tuple[int, ...], int], max_height: int) -> List[Tuple[Tuple[int, ...], int]]:
    """Breadth-first exploration of the reflection graph, cut off at a height bound."""
    seen = {root}
    frontier = [root]
    order = [root]
    while frontier:
        nxt = []
        for x, d in frontier:
            for _, node in children(x, d):
                if node[1] <= max_height and node not in seen:
                    seen.add(node)
                    nxt.append(node)
                    order.append(node)
        frontier = nxt
    return order


def verify_dichotomy(height_bound: int = 60) -> Tuple[int, int]:
    """Brute-force check: every quadruple of height <= bound has 6 or 7 children."""
    import math
    six = seven = 0
    for d in range(1, height_bound + 1):
        for a in range(1, d + 1):
            for b in range(a, d + 1):
                r = d * d - a * a - b * b
                if r <= 0:
                    break
                c = math.isqrt(r)
                if c * c == r and c >= b:
                    k = sum(1 for _ in children((a, b, c), d))
                    assert k == branching_number(a, b, c, d)
                    assert weak_defect(a, b, c, d) == harmonic_defect(a, b, c)
                    if k == 6:
                        six += 1
                    else:
                        seven += 1
    return six, seven


if __name__ == "__main__":
    print("six/seven counts up to height 60:", verify_dichotomy(60))
    print("children of (1,2,2;3):")
    for eps, node in children((1, 2, 2), 3):
        print("   ", eps, "->", node)
